def transform(grid):
    # Markers on the horizontal baseline generate vertical rays upward.
    g=[row[:] for row in grid]
    r=next((i for i,row in enumerate(g) if any(v in (2,8) for v in row)), None)
    if r is None: return g
    for c,v in enumerate(g[r]):
        if v in (2,8):
            height = 4 if v == 2 else 3
